def resolve(path, cwd, links):
    if path is None or cwd is None or links is None:
        return None

    # Start with cwd if path is relative
    if not path.startswith('/'):
        if not cwd.startswith('/'):
            return None
        current = cwd
    else:
        current = '/'
        path = path[1:]  # Remove leading slash for processing

    # Split path into components, filter empty strings and '.'
    components = [c for c in path.split('/') if c and c != '.']

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        comp = components[i]

        if comp == '..':
            # Move to parent
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if not current:
                    current = '/'
            i += 1
        else:
            # Append component
            if current == '/':
                candidate = '/' + comp
            else:
                candidate = current + '/' + comp

            # Check if it's a symlink
            if candidate in links:
                link_count += 1
                if link_count > max_links:
                    return None

                target = links[candidate]

                # Process the target
                if target.startswith('/'):
                    # Absolute target
                    current = '/'
                    target_path = target[1:]
                else:
                    # Relative target - relative to the directory containing the link
                    if candidate == '/':
                        current = '/'
                    else:
                        current = candidate.rsplit('/', 1)[0]
                        if not current:
                            current = '/'
                    target_path = target

                # Get remaining components from current iteration onwards
                remaining = components[i+1:]

                # Parse target into components
                target_components = [c for c in target_path.split('/') if c and c != '.']

                # Prepend target components
                components = target_components + remaining
                i = 0
            else:
                # Not a symlink, just move current to candidate
                current = candidate
                i += 1

    # Remove trailing slash except for '/'
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

